insert into public.ta_lessons(course_slug,lesson_no,title_pl,material) values
('ludwisarz',0,'1. Anatomia dzwonu: korona, płaszcz, wieniec, serce','{"module":1,"curriculum_revision":7,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"ludwisarz-anatomia","sections":[{"heading":"Zrozum materiał i zjawisko","text":"Ludwisarz nie wytwarza dowolnej metalowej czaszy. Dzwon ma koronę (element mocowania), górną strefę ramienia/shoulder, płaszcz o zmiennej grubości, dolną strefę uderzenia zwaną soundbow, krawędź wylotu/lip oraz osobny element uderzający — serce, czyli clapper. Nie wszystkie dzwony mają identyczne okucia i sposób zawieszenia; dzwony wieżowe, ręczne i dekoracyjne różnią się wymaganiami."},{"heading":"Metoda i kontrola","text":"Na przekroju dzwonu oznacz zewnętrzny i wewnętrzny profil oraz grubość ścianki w trzech strefach. Dźwięk zależy od geometrii i materiału całej czaszy, więc samo dopasowanie średnicy dolnej nie gwarantuje poprawnego brzmienia. Korona i serce uczestniczą w obciążeniach konstrukcyjnych i nie powinny być ''dorabiane na oko''."},{"heading":"Przykład","text":"Dwa dzwony mają tę samą średnicę wylotu, ale jeden ma znacznie grubszy soundbow. Nie można wnioskować, że będą mieć ten sam ton lub naprężenia; niezbędny jest profil całego odlewu."},{"heading":"Problem zawodowy","text":"Klient zamówił dzwon do wieży, a projekt pokazuje wyłącznie widok z przodu bez zawieszenia. Wypisz brakujące informacje: profil wewnętrzny, korona, serce, sposób zawieszenia, obciążenia i warunki odbioru."},{"heading":"Zadanie i weryfikacja","text":"Narysuj podpisany przekrój dzwonu oraz widok od przodu. Zaznacz pięć stref i rolę serca, następnie przygotuj kartę brakujących wymiarów oraz wymaganych dokumentów."}],"references":[{"label":"Źródło techniczne","url":"https://www.bells.org/how-bells-are-made"}],"learning":{"intro":"Ludwisarz nie wytwarza dowolnej metalowej czaszy. Dzwon ma koronę (element mocowania), górną strefę ramienia/shoulder, płaszcz o zmiennej grubości, dolną strefę uderzenia zwaną soundbow, krawędź wylotu/lip oraz osobny element uderzający — serce, czyli clapper. Nie wszystkie dzwony mają identyczne okucia i sposób zawieszenia; dzwony wieżowe, ręczne i dekoracyjne różnią się wymaganiami.","situation":"Klient zamówił dzwon do wieży, a projekt pokazuje wyłącznie widok z przodu bez zawieszenia. Wypisz brakujące informacje: profil wewnętrzny, korona, serce, sposób zawieszenia, obciążenia i warunki odbioru.","task":"Narysuj podpisany przekrój dzwonu oraz widok od przodu. Zaznacz pięć stref i rolę serca, następnie przygotuj kartę brakujących wymiarów oraz wymaganych dokumentów.","question":"Która część dzwonu jest szczególnie związana z miejscem uderzenia serca?","options":["Korona mocująca do zawieszenia.","Wieniec uderzeniowy (soundbow).","Zewnętrzny napis na płaszczu.","Sama rama dzwonnicy."],"correct":1,"example":"Wieniec uderzeniowy (soundbow).","explanation":"Soundbow to pogrubiona strefa w pobliżu wylotu, w którą w tradycyjnym dzwonie uderza serce.","feedback":["Sprawdź pojęcia i dane. Soundbow to pogrubiona strefa w pobliżu wylotu, w którą w tradycyjnym dzwonie uderza serce.","Tak. Soundbow to pogrubiona strefa w pobliżu wylotu, w którą w tradycyjnym dzwonie uderza serce.","Sprawdź pojęcia i dane. Soundbow to pogrubiona strefa w pobliżu wylotu, w którą w tradycyjnym dzwonie uderza serce.","Sprawdź pojęcia i dane. Soundbow to pogrubiona strefa w pobliżu wylotu, w którą w tradycyjnym dzwonie uderza serce."]}}'::jsonb),
('ludwisarz',1,'2. Brąz dzwonowy: miedź, cyna i własności stopu','{"module":1,"curriculum_revision":7,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"ludwisarz-stop","sections":[{"heading":"Zrozum materiał i zjawisko","text":"Tradycyjny brąz dzwonowy jest stopem miedzi i cyny. Znana proporcja masowa 78% Cu i 22% Sn jest często przywoływanym składem, ale nie jest obowiązkowym składem każdego historycznego dzwonu. Mechaniczne i akustyczne zachowanie zależą także od odlewania, mikrostruktury, porowatości i obecności domieszek. Brąz dzwonowy nie jest synonimem mosiądzu, w którym głównym dodatkiem stopowym jest cynk."},{"heading":"Metoda i kontrola","text":"Ćwiczenie bezpieczne polega na obliczaniu składu nominalnego i odczytywaniu dokumentacji materiałowej. Dla 50 kg stopu 78/22: miedź 0,78×50=39 kg, cyna 0,22×50=11 kg. Nie oznacza to rzeczywistej receptury do zalewu: przy wytwarzaniu dochodzą straty procesu, kontrola składu i normy właściwe dla danego zakładu."},{"heading":"Przykład","text":"W opisie materiału podano ''brąz 78/22'' dla 30 kg. Odpowiada to nominalnie 23,4 kg miedzi oraz 6,6 kg cyny. Błędem jest policzenie 22% od masy samej miedzi zamiast od całości stopu."},{"heading":"Problem zawodowy","text":"Dostawca twierdzi, że dowolny mosiądz jest równoważny brązowi dzwonowemu, bo oba mają kolor żółty. Należy odrzucić argument wyglądu i przeanalizować skład oraz wymagania akustyczne."},{"heading":"Zadanie i weryfikacja","text":"W tabeli policz udział Cu/Sn dla nominalnych partii 10, 30 i 50 kg przy proporcji 78/22. Dopisz, dlaczego rzeczywisty stop wymaga analizy laboratoryjnej i kontroli procesu."}],"references":[{"label":"Źródło techniczne","url":"https://www.mdpi.com/2075-4701/12/11/1776"}],"learning":{"intro":"Tradycyjny brąz dzwonowy jest stopem miedzi i cyny. Znana proporcja masowa 78% Cu i 22% Sn jest często przywoływanym składem, ale nie jest obowiązkowym składem każdego historycznego dzwonu. Mechaniczne i akustyczne zachowanie zależą także od odlewania, mikrostruktury, porowatości i obecności domieszek. Brąz dzwonowy nie jest synonimem mosiądzu, w którym głównym dodatkiem stopowym jest cynk.","situation":"Dostawca twierdzi, że dowolny mosiądz jest równoważny brązowi dzwonowemu, bo oba mają kolor żółty. Należy odrzucić argument wyglądu i przeanalizować skład oraz wymagania akustyczne.","task":"W tabeli policz udział Cu/Sn dla nominalnych partii 10, 30 i 50 kg przy proporcji 78/22. Dopisz, dlaczego rzeczywisty stop wymaga analizy laboratoryjnej i kontroli procesu.","question":"Dla hipotetycznych 30 kg brązu 78% Cu i 22% Sn ile wynosi masa cyny?","options":["7,8 kg.","6,6 kg.","22 kg.","23,4 kg."],"correct":1,"example":"6,6 kg.","explanation":"0,22×30 kg=6,6 kg cyny; 23,4 kg to miedź.","feedback":["Sprawdź pojęcia i dane. 0,22×30 kg=6,6 kg cyny; 23,4 kg to miedź.","Tak. 0,22×30 kg=6,6 kg cyny; 23,4 kg to miedź.","Sprawdź pojęcia i dane. 0,22×30 kg=6,6 kg cyny; 23,4 kg to miedź.","Sprawdź pojęcia i dane. 0,22×30 kg=6,6 kg cyny; 23,4 kg to miedź."]}}'::jsonb),
('ludwisarz',2,'3. Rysunek i forma: rdzeń, płaszcz zewnętrzny i przestrzeń odlewu','{"module":1,"curriculum_revision":7,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"ludwisarz-forma","sections":[{"heading":"Zrozum materiał i zjawisko","text":"W odlewie pustego dzwonu przestrzeń między wewnętrznym rdzeniem (core) a zewnętrzną formą (cope/mantle) jest miejscem przyszłej ścianki metalowej. Jej grubość zmienia się wzdłuż wysokości dzwonu. Profil wyznacza się z pomocą szablonów zwanych strickle boards lub crooks; to ważniejsza informacja niż sam wygląd końcowej powierzchni. W określonych tradycjach występuje także model pośredni, tzw. fałszywy dzwon."},{"heading":"Metoda i kontrola","text":"Na przekroju symetrycznym oznacz oś pionową, profil rdzenia, profil formy zewnętrznej, przestrzeń metalową, wlew i odpowietrzenia jako elementy koncepcyjne. Jeśli w jednej wysokości promień zewnętrzny wynosi 120 mm, a wewnętrzny 105 mm, grubość promieniowa wynosi 15 mm. Pomiar w jednym miejscu nie opisuje całego przekroju ani pasowania szablonu."},{"heading":"Przykład","text":"Uczeń mierzy średnicę zewnętrzną 240 mm i wewnętrzną 210 mm, po czym błędnie podaje grubość 30 mm. Prawidłowo w modelu osiowym: (240−210)/2=15 mm, ponieważ różnica średnic obejmuje obie ścianki."},{"heading":"Problem zawodowy","text":"Na rysunku profil rdzenia styka się z profilem zewnętrznym przy wylocie. To brak przestrzeni dla metalu, a nie poprawna geometra odlewu. Zaznacz błąd i potrzebne wymiary."},{"heading":"Zadanie i weryfikacja","text":"Narysuj przekrój 1:5 z osiami i dwiema powierzchniami formy. Oblicz 15 mm grubości z podanych średnic, a potem oznacz miejsca wymagające niezależnego pomiaru i oceny technologicznej."}],"references":[{"label":"Źródło techniczne","url":"https://heritagecrafts.org.uk/craft/bell-founding/"}],"learning":{"intro":"W odlewie pustego dzwonu przestrzeń między wewnętrznym rdzeniem (core) a zewnętrzną formą (cope/mantle) jest miejscem przyszłej ścianki metalowej. Jej grubość zmienia się wzdłuż wysokości dzwonu. Profil wyznacza się z pomocą szablonów zwanych strickle boards lub crooks; to ważniejsza informacja niż sam wygląd końcowej powierzchni. W określonych tradycjach występuje także model pośredni, tzw. fałszywy dzwon.","situation":"Na rysunku profil rdzenia styka się z profilem zewnętrznym przy wylocie. To brak przestrzeni dla metalu, a nie poprawna geometra odlewu. Zaznacz błąd i potrzebne wymiary.","task":"Narysuj przekrój 1:5 z osiami i dwiema powierzchniami formy. Oblicz 15 mm grubości z podanych średnic, a potem oznacz miejsca wymagające niezależnego pomiaru i oceny technologicznej.","question":"Przy średnicy zewnętrznej 240 mm i wewnętrznej 210 mm, jaka jest modelowa grubość ścianki w tej wysokości?","options":["15 mm.","30 mm.","45 mm.","210 mm."],"correct":0,"example":"15 mm.","explanation":"Grubość na jedną stronę to połowa różnicy średnic: (240−210)/2=15 mm.","feedback":["Tak. Grubość na jedną stronę to połowa różnicy średnic: (240−210)/2=15 mm.","Sprawdź pojęcia i dane. Grubość na jedną stronę to połowa różnicy średnic: (240−210)/2=15 mm.","Sprawdź pojęcia i dane. Grubość na jedną stronę to połowa różnicy średnic: (240−210)/2=15 mm.","Sprawdź pojęcia i dane. Grubość na jedną stronę to połowa różnicy średnic: (240−210)/2=15 mm."]}}'::jsonb),
('ludwisarz',3,'4. Technologia form: glina formierska, piasek i metoda wosku traconego','{"module":1,"curriculum_revision":7,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"ludwisarz-forma","sections":[{"heading":"Zrozum materiał i zjawisko","text":"Historyczne formy dzwonowe wykonywano m.in. z gliny, piasku, włókien i innych składników dostosowanych do technologii. W metodzie fałszywego dzwonu tworzy się tymczasową geometrię, którą następnie usuwa, pozostawiając przestrzeń między rdzeniem a płaszczem. Metoda wosku traconego może służyć przygotowaniu szczegółowych dekoracji; współczesne odlewnie stosują również formy piaskowe. Nie ma jednej metody stosowanej w każdej odlewni i epoce."},{"heading":"Metoda i kontrola","text":"Porównaj na schemacie trzy etapy: rdzeń, model/fałszywy dzwon, zewnętrzna forma po usunięciu modelu. Nie należy samodzielnie odtwarzać suszenia formy, składu mas ani zalewania stopem na podstawie ogólnego opisu. Niewystarczająco przygotowana forma lub wilgoć mogą stworzyć zagrożenie podczas kontaktu z ciekłym metalem."},{"heading":"Przykład","text":"W odlewni A profile formy wykonuje się przy pomocy szablonu obrotowego i mieszanki gliniastej, w B wykorzystuje formy piaskowe o określonym sposobie wiązania. Obie technologie mogą prowadzić do odlewu dzwonu, ale są to inne procesy, o różnych kontrolach i ograniczeniach."},{"heading":"Problem zawodowy","text":"Klient przyniósł projekt dzwonu z bardzo drobnym napisem. Ustal, jak przenieść informację do formy i jak ocenić, czy detale będą możliwe do odtworzenia po odlewie."},{"heading":"Zadanie i weryfikacja","text":"Zrób tabelę: technologia, rodzaj modelu, rdzeń, odwzorowanie napisu, ryzyko wady, wymagane doświadczenie. Podpisz kolejność przygotowania geometrycznego formy bez wykonywania realnego odlewu."}],"references":[{"label":"Źródło techniczne","url":"https://heritagecrafts.org.uk/craft/bell-founding/"}],"learning":{"intro":"Historyczne formy dzwonowe wykonywano m.in. z gliny, piasku, włókien i innych składników dostosowanych do technologii. W metodzie fałszywego dzwonu tworzy się tymczasową geometrię, którą następnie usuwa, pozostawiając przestrzeń między rdzeniem a płaszczem. Metoda wosku traconego może służyć przygotowaniu szczegółowych dekoracji; współczesne odlewnie stosują również formy piaskowe. Nie ma jednej metody stosowanej w każdej odlewni i epoce.","situation":"Klient przyniósł projekt dzwonu z bardzo drobnym napisem. Ustal, jak przenieść informację do formy i jak ocenić, czy detale będą możliwe do odtworzenia po odlewie.","task":"Zrób tabelę: technologia, rodzaj modelu, rdzeń, odwzorowanie napisu, ryzyko wady, wymagane doświadczenie. Podpisz kolejność przygotowania geometrycznego formy bez wykonywania realnego odlewu.","question":"Co tworzy metalową ściankę pustego dzwonu podczas odlewania?","options":["Materiał samego rdzenia.","Wosk pozostawiony w środku gotowego dzwonu.","Metal wprowadzony w szczelinę między rdzeniem a formą zewnętrzną.","Zewnętrzna warstwa farby po wyjęciu modelu."],"correct":2,"example":"Metal wprowadzony w szczelinę między rdzeniem a formą zewnętrzną.","explanation":"Szczelina między rdzeniem i formą zewnętrzną jest przestrzenią wypełnianą metalem.","feedback":["Sprawdź pojęcia i dane. Szczelina między rdzeniem i formą zewnętrzną jest przestrzenią wypełnianą metalem.","Sprawdź pojęcia i dane. Szczelina między rdzeniem i formą zewnętrzną jest przestrzenią wypełnianą metalem.","Tak. Szczelina między rdzeniem i formą zewnętrzną jest przestrzenią wypełnianą metalem.","Sprawdź pojęcia i dane. Szczelina między rdzeniem i formą zewnętrzną jest przestrzenią wypełnianą metalem."]}}'::jsonb),
('ludwisarz',4,'5. Napisy i dekoracje: od wzoru do odcisku w formie','{"module":2,"curriculum_revision":7,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"ludwisarz-forma","sections":[{"heading":"Zrozum materiał i zjawisko","text":"Litery, ornamenty, daty i znaki odlewni są integralną częścią zabytkowych dzwonów. W metodach z odwróconym odwzorowaniem wzór w formie musi zostać przygotowany tak, żeby po odlaniu napis był czytelny we właściwym kierunku. W tradycyjnym procesie można stosować elementy woskowe albo stemple odwzorowujące wzór bezpośrednio w powierzchni formy; sposób zależy od pracowni."},{"heading":"Metoda i kontrola","text":"Na papierze wykonaj ćwiczenie lustrzanego napisu ''2026'', rozróżniając napis docelowy, negatyw formy i widok odlanej powierzchni. Ustal miejsce napisu na profilu, minimalne odstępy między znakami oraz obowiązek zachowania oryginalnych informacji w przypadku renowacji zabytku."},{"heading":"Przykład","text":"Na projekcie zamówienia napis ''ANNO 2026'' jest prawidłowo czytelny. Uczeń bezmyślnie kopiuje go do lustrzanej formy jako widok gotowego wyrobu. Po odbiciu kierunek może się odwrócić, jeśli pominięto koncepcję pozytywu i negatywu."},{"heading":"Problem zawodowy","text":"Muzeum zamawia kopię dzwonu z historyczną sygnaturą. Nie wolno jej ''upiększać'' przez zmianę liter i dat bez udokumentowanej decyzji oraz rozróżnienia oryginału od kopii."},{"heading":"Zadanie i weryfikacja","text":"Zaprojektuj pas ornamentalny na papierowej formie i oznacz, gdzie znajduje się pozytyw, a gdzie negatyw. Dodaj kartę kontroli tekstu: treść, orientacja, położenie, dowód źródłowy i zatwierdzenie."}],"references":[{"label":"Źródło techniczne","url":"https://heritagecrafts.org.uk/craft/bell-founding/"}],"learning":{"intro":"Litery, ornamenty, daty i znaki odlewni są integralną częścią zabytkowych dzwonów. W metodach z odwróconym odwzorowaniem wzór w formie musi zostać przygotowany tak, żeby po odlaniu napis był czytelny we właściwym kierunku. W tradycyjnym procesie można stosować elementy woskowe albo stemple odwzorowujące wzór bezpośrednio w powierzchni formy; sposób zależy od pracowni.","situation":"Muzeum zamawia kopię dzwonu z historyczną sygnaturą. Nie wolno jej ''upiększać'' przez zmianę liter i dat bez udokumentowanej decyzji oraz rozróżnienia oryginału od kopii.","task":"Zaprojektuj pas ornamentalny na papierowej formie i oznacz, gdzie znajduje się pozytyw, a gdzie negatyw. Dodaj kartę kontroli tekstu: treść, orientacja, położenie, dowód źródłowy i zatwierdzenie.","question":"Dlaczego przed wykonaniem liter w formie trzeba odróżnić pozytyw napisu od jego negatywu?","options":["Bo to wpływa jedynie na kolor powierzchni.","Bo powierzchnia formy i gotowego odlewu odwzorowują znaki we właściwych kierunkach po przeniesieniu.","Bo napis nigdy nie ma znaczenia historycznego.","Bo wszystkie techniki formowania zawsze mają identyczny sposób nanoszenia liter."],"correct":1,"example":"Bo powierzchnia formy i gotowego odlewu odwzorowują znaki we właściwych kierunkach po przeniesieniu.","explanation":"Kierunek i sposób odwzorowania zależą od tego, czy patrzymy na model, negatyw czy gotowy wyrób.","feedback":["Sprawdź pojęcia i dane. Kierunek i sposób odwzorowania zależą od tego, czy patrzymy na model, negatyw czy gotowy wyrób.","Tak. Kierunek i sposób odwzorowania zależą od tego, czy patrzymy na model, negatyw czy gotowy wyrób.","Sprawdź pojęcia i dane. Kierunek i sposób odwzorowania zależą od tego, czy patrzymy na model, negatyw czy gotowy wyrób.","Sprawdź pojęcia i dane. Kierunek i sposób odwzorowania zależą od tego, czy patrzymy na model, negatyw czy gotowy wyrób."]}}'::jsonb),
('ludwisarz',5,'6. Skurcz odlewniczy i kontrola wymiarowa: model a gotowy dzwon','{"module":2,"curriculum_revision":7,"editorial_status":"review_needed","lesson_kind":"technical_curriculum","illustration":"ludwisarz-forma","sections":[{"heading":"Zrozum materiał i zjawisko","text":"Metal podczas krzepnięcia i chłodzenia może zmieniać wymiary. Projekt formy musi uwzględniać specyfikę stopu, geometrię, masę i technologię. Nie istnieje jedna liczba skurczu pasująca do wszystkich odlewów dzwonowych. Rozdziel skurcz liniowy przyjmowany do projektowania od rzeczywistych lokalnych zmian grubości i wpływu wad krzepnięcia."},{"heading":"Metoda i kontrola","text":"Wyłącznie jako zadanie matematyczne przyjmij hipotetyczny skurcz liniowy 1%. Aby po ostygnięciu uzyskać 400 mm, wymiar początkowy modelu musiałby wynosić 400/(1−0,01)=404,04 mm. To nie jest zalecenie technologiczne dla brązu 78/22. Prawidłowy naddatek dobiera technolog na podstawie danych procesu, a następnie sprawdza na odlewach próbnych."},{"heading":"Przykład","text":"Uczeń dodaje 1% do wymiaru 400 mm i wpisuje 404 mm. Jest to bliskie wynikowi 404,04 mm, ale dokładny wzór odnosi procent do wymiaru przed skurczem. Przy dokładnej produkcji różnica i źródło założenia muszą być jawne."},{"heading":"Problem zawodowy","text":"Wymiary dzwonu po odlaniu są niezgodne w trzech strefach. Nie wolno zakładać, że samo jednolite skalowanie projektu rozwiąże problem lokalnej deformacji. Potrzebne są pomiary profilu i analiza procesu."},{"heading":"Zadanie i weryfikacja","text":"Policz przykładowy początkowy wymiar dla celu 400 mm przy skurczu 1% i przy 2% (dla drugiego 408,16 mm). Narysuj dwie lokalizacje kontrolne na przekroju i oddziel założenie matematyczne od danych technologicznych."}],"references":[{"label":"Źródło techniczne","url":"https://www.mdpi.com/2075-4701/12/11/1776"}],"learning":{"intro":"Metal podczas krzepnięcia i chłodzenia może zmieniać wymiary. Projekt formy musi uwzględniać specyfikę stopu, geometrię, masę i technologię. Nie istnieje jedna liczba skurczu pasująca do wszystkich odlewów dzwonowych. Rozdziel skurcz liniowy przyjmowany do projektowania od rzeczywistych lokalnych zmian grubości i wpływu wad krzepnięcia.","situation":"Wymiary dzwonu po odlaniu są niezgodne w trzech strefach. Nie wolno zakładać, że samo jednolite skalowanie projektu rozwiąże problem lokalnej deformacji. Potrzebne są pomiary profilu i analiza procesu.","task":"Policz przykładowy początkowy wymiar dla celu 400 mm przy skurczu 1% i przy 2% (dla drugiego 408,16 mm). Narysuj dwie lokalizacje kontrolne na przekroju i oddziel założenie matematyczne od danych technologicznych.","question":"W ćwiczeniu z hipotetycznym skurczem 1% wymiar gotowy wynosi 400 mm. Jaki wymiar początkowy wynika ze wzoru?","options":["396 mm.","400 mm.","404,04 mm.","440 mm."],"correct":2,"example":"404,04 mm.","explanation":"400/(1−0,01)=404,04 mm. Założenie 1% jest dydaktyczne, nie receptą odlewniczą.","feedback":["Sprawdź pojęcia i dane. 400/(1−0,01)=404,04 mm. Założenie 1% jest dydaktyczne, nie receptą odlewniczą.","Sprawdź pojęcia i dane. 400/(1−0,01)=404,04 mm. Założenie 1% jest dydaktyczne, nie receptą odlewniczą.","Tak. 400/(1−0,01)=404,04 mm. Założenie 1% jest dydaktyczne, nie receptą odlewniczą.","Sprawdź pojęcia i dane. 400/(1−0,01)=404,04 mm. Założenie 1% jest dydaktyczne, nie receptą odlewniczą."]}}'::jsonb),
('ludwisarz',6,'7. BHP ciekłego metalu i kontrola wilgoci','{"module":2,"curriculum_revision":7,"editorial_status":"review_needed","illustration":"Wilgoć może powodować eksplozję parową.","sections":[{"heading":"Definicje i materiał","text":"Woda we wsadzie lub formie może gwałtownie zamienić się w parę i rozprysnąć ciekły metal. Praktyka wymaga wykwalifikowanej załogi, planu awaryjnego i kontroli stanowiska."},{"heading":"Sytuacja zawodowa","text":"W zakładzie znaleziono wilgotny wsad po deszczu. Pracę należy wstrzymać i zgłosić problem."},{"heading":"Ćwiczenie bezpieczne","text":"Sporządź na papierze analizę SJA dziesięciu zagrożeń: ryzyko, prewencja, odpowiedzialny, decyzja."},{"heading":"Analiza ryzyka i weryfikacja","text":"Uczeń musi uzasadnić wynik, wskazać dane brakujące oraz oddzielić ćwiczenie edukacyjne od pracy w odlewni."},{"heading":"Ograniczenia","text":"Realny odlew, strojenie mechaniczne i montaż wymagają wykwalifikowanego specjalisty oraz odpowiedniej dokumentacji."}],"references":[{"label":"Heritage Crafts","url":"https://heritagecrafts.org.uk/craft/bell-founding/"}],"learning":{"intro":"Woda we wsadzie lub formie może gwałtownie zamienić się w parę i rozprysnąć ciekły metal. Praktyka wymaga wykwalifikowanej załogi, planu awaryjnego i kontroli stanowiska.","situation":"W zakładzie znaleziono wilgotny wsad po deszczu. Pracę należy wstrzymać i zgłosić problem.","task":"Sporządź na papierze analizę SJA dziesięciu zagrożeń: ryzyko, prewencja, odpowiedzialny, decyzja.","question":"Dlaczego wilgotny wsad jest zagrożeniem?","options":["Może spowodować gwałtowny rozprysk przez parę.","Zmienia wyłącznie kolor metalu.","Automatycznie zmniejsza masę odlewu.","Zastępuje odpowietrzenie formy."],"correct":0,"example":"Może spowodować gwałtowny rozprysk przez parę.","explanation":"ludwisarz-bhp","feedback":["Poprawnie. ludwisarz-bhp","Błędnie. ludwisarz-bhp","Błędnie. ludwisarz-bhp","Błędnie. ludwisarz-bhp"]}}'::jsonb),
('ludwisarz',7,'8. Porowatość, jamy skurczowe i pęknięcia','{"module":2,"curriculum_revision":7,"editorial_status":"review_needed","illustration":"Pory wewnętrzne mogą wymagać badań nieniszczących.","sections":[{"heading":"Definicje i materiał","text":"Wady odlewu to różne nieciągłości: pory, pustki skurczowe, wtrącenia i pęknięcia. Gładka powierzchnia nie gwarantuje braku wad wewnętrznych."},{"heading":"Sytuacja zawodowa","text":"Odlew ma idealny wygląd, ale badanie wykazało pustkę. Należy udokumentować wskazanie i ocenić według kryteriów."},{"heading":"Ćwiczenie bezpieczne","text":"Na schemacie przekroju narysuj cztery wady i kartę kontroli ośmiu fikcyjnych odlewów."},{"heading":"Analiza ryzyka i weryfikacja","text":"Uczeń musi uzasadnić wynik, wskazać dane brakujące oraz oddzielić ćwiczenie edukacyjne od pracy w odlewni."},{"heading":"Ograniczenia","text":"Realny odlew, strojenie mechaniczne i montaż wymagają wykwalifikowanego specjalisty oraz odpowiedniej dokumentacji."}],"references":[{"label":"Heritage Crafts","url":"https://heritagecrafts.org.uk/craft/bell-founding/"}],"learning":{"intro":"Wady odlewu to różne nieciągłości: pory, pustki skurczowe, wtrącenia i pęknięcia. Gładka powierzchnia nie gwarantuje braku wad wewnętrznych.","situation":"Odlew ma idealny wygląd, ale badanie wykazało pustkę. Należy udokumentować wskazanie i ocenić według kryteriów.","task":"Na schemacie przekroju narysuj cztery wady i kartę kontroli ośmiu fikcyjnych odlewów.","question":"Co może pozostać niewidoczne po polerowaniu?","options":["Wypukły napis.","Porowatość wewnętrzna.","Dekoracja zewnętrzna.","Ślad narzędzia na zewnątrz."],"correct":1,"example":"Porowatość wewnętrzna.","explanation":"ludwisarz-wady","feedback":["Błędnie. ludwisarz-wady","Poprawnie. ludwisarz-wady","Błędnie. ludwisarz-wady","Błędnie. ludwisarz-wady"]}}'::jsonb),
('ludwisarz',8,'9. Akustyka: hum, prime, tierce, quint i nominal','{"module":3,"curriculum_revision":7,"editorial_status":"review_needed","illustration":"Oktawa oznacza stosunek częstotliwości 2:1.","sections":[{"heading":"Definicje i materiał","text":"Dzwon wytwarza kilka rezonansów. Analizuje się hum, prime, tierce, quint i nominal. Proporcje zależą od profilu i stopu, a nie wyłącznie średnicy."},{"heading":"Sytuacja zawodowa","text":"Model prime=500 Hz, hum=250 Hz, nominal=1000 Hz, quint około 750 Hz i tierce około 600 Hz jest wyłącznie dydaktyczny."},{"heading":"Ćwiczenie bezpieczne","text":"Narysuj wykres pięciu składowych i oblicz stosunek nominal/prime."},{"heading":"Analiza ryzyka i weryfikacja","text":"Uczeń musi uzasadnić wynik, wskazać dane brakujące oraz oddzielić ćwiczenie edukacyjne od pracy w odlewni."},{"heading":"Ograniczenia","text":"Realny odlew, strojenie mechaniczne i montaż wymagają wykwalifikowanego specjalisty oraz odpowiedniej dokumentacji."}],"references":[{"label":"Heritage Crafts","url":"https://heritagecrafts.org.uk/craft/bell-founding/"}],"learning":{"intro":"Dzwon wytwarza kilka rezonansów. Analizuje się hum, prime, tierce, quint i nominal. Proporcje zależą od profilu i stopu, a nie wyłącznie średnicy.","situation":"Model prime=500 Hz, hum=250 Hz, nominal=1000 Hz, quint około 750 Hz i tierce około 600 Hz jest wyłącznie dydaktyczny.","task":"Narysuj wykres pięciu składowych i oblicz stosunek nominal/prime.","question":"Jeżeli prime=500 Hz, nominal oktawę wyżej ma...","options":["750 Hz.","250 Hz.","1000 Hz.","1500 Hz."],"correct":2,"example":"1000 Hz.","explanation":"ludwisarz-akustyka","feedback":["Błędnie. ludwisarz-akustyka","Błędnie. ludwisarz-akustyka","Poprawnie. ludwisarz-akustyka","Błędnie. ludwisarz-akustyka"]}}'::jsonb),
('ludwisarz',9,'10. Strojenie: widmo, profil i granice korekty','{"module":3,"curriculum_revision":7,"editorial_status":"review_needed","illustration":"Geometria wpływa na wiele składowych jednocześnie.","sections":[{"heading":"Definicje i materiał","text":"Strojenie polega na analizie rezonansów i fachowej zmianie profilu. Usunięcie metalu może inaczej wpłynąć na różne składowe i nie jest odwracalne."},{"heading":"Sytuacja zawodowa","text":"Prime docelowe 500 Hz, zmierzone 493 Hz: różnica +7 Hz. Nominal 1000 vs 992 Hz: +8 Hz. Nie wynika z tego miejsce skrawania."},{"heading":"Ćwiczenie bezpieczne","text":"Ułóż tabelę pięciu składowych: cel, pomiar, różnica, decyzja, brakujące dane. Nie obrabiaj metalu."},{"heading":"Analiza ryzyka i weryfikacja","text":"Uczeń musi uzasadnić wynik, wskazać dane brakujące oraz oddzielić ćwiczenie edukacyjne od pracy w odlewni."},{"heading":"Ograniczenia","text":"Realny odlew, strojenie mechaniczne i montaż wymagają wykwalifikowanego specjalisty oraz odpowiedniej dokumentacji."}],"references":[{"label":"Heritage Crafts","url":"https://heritagecrafts.org.uk/craft/bell-founding/"}],"learning":{"intro":"Strojenie polega na analizie rezonansów i fachowej zmianie profilu. Usunięcie metalu może inaczej wpłynąć na różne składowe i nie jest odwracalne.","situation":"Prime docelowe 500 Hz, zmierzone 493 Hz: różnica +7 Hz. Nominal 1000 vs 992 Hz: +8 Hz. Nie wynika z tego miejsce skrawania.","task":"Ułóż tabelę pięciu składowych: cel, pomiar, różnica, decyzja, brakujące dane. Nie obrabiaj metalu.","question":"Dlaczego pomiar jedynie prime nie wystarcza do strojenia?","options":["Bo skrawanie może zmienić wiele rezonansów.","Bo dzwon ma tylko jedną składową.","Bo częstotliwości nie da się zmierzyć.","Bo skrawanie nigdy nie zmienia profilu."],"correct":0,"example":"Bo skrawanie może zmienić wiele rezonansów.","explanation":"ludwisarz-akustyka","feedback":["Poprawnie. ludwisarz-akustyka","Błędnie. ludwisarz-akustyka","Błędnie. ludwisarz-akustyka","Błędnie. ludwisarz-akustyka"]}}'::jsonb),
('ludwisarz',10,'11. Zawieszenie, korona, jarzmo i serce','{"module":3,"curriculum_revision":7,"editorial_status":"review_needed","illustration":"Ruch i uderzenia zwiększają oraz zmieniają kierunki sił.","sections":[{"heading":"Definicje i materiał","text":"Zawieszenie przenosi ciężar i obciążenia dynamiczne. Sama masa nie określa nośności korony, jarzma, ramy i zamocowań."},{"heading":"Sytuacja zawodowa","text":"Dla 200 kg statyczny ciężar to około 1962 N. Kołysanie i uderzenia wymagają dodatkowej analizy konstrukcji."},{"heading":"Ćwiczenie bezpieczne","text":"Narysuj tor sił i wskaż brakujące parametry do projektu zawieszenia."},{"heading":"Analiza ryzyka i weryfikacja","text":"Uczeń musi uzasadnić wynik, wskazać dane brakujące oraz oddzielić ćwiczenie edukacyjne od pracy w odlewni."},{"heading":"Ograniczenia","text":"Realny odlew, strojenie mechaniczne i montaż wymagają wykwalifikowanego specjalisty oraz odpowiedniej dokumentacji."}],"references":[{"label":"Heritage Crafts","url":"https://heritagecrafts.org.uk/craft/bell-founding/"}],"learning":{"intro":"Zawieszenie przenosi ciężar i obciążenia dynamiczne. Sama masa nie określa nośności korony, jarzma, ramy i zamocowań.","situation":"Dla 200 kg statyczny ciężar to około 1962 N. Kołysanie i uderzenia wymagają dodatkowej analizy konstrukcji.","task":"Narysuj tor sił i wskaż brakujące parametry do projektu zawieszenia.","question":"Dlaczego 1962 N nie wystarcza do projektu mocowania dzwonu ruchomego?","options":["Bo nie ma grawitacji.","Bo dochodzą obciążenia dynamiczne.","Bo liczy się tylko kolor stopu.","Bo masa nie wpływa na siły."],"correct":1,"example":"Bo dochodzą obciążenia dynamiczne.","explanation":"ludwisarz-anatomia","feedback":["Błędnie. ludwisarz-anatomia","Poprawnie. ludwisarz-anatomia","Błędnie. ludwisarz-anatomia","Błędnie. ludwisarz-anatomia"]}}'::jsonb),
('ludwisarz',11,'12. Projekt dzwonu ekspozycyjnego i protokół odbioru','{"module":3,"curriculum_revision":7,"editorial_status":"review_needed","illustration":"0,22×30=6,6 kg.","sections":[{"heading":"Definicje i materiał","text":"Projekt dydaktyczny obejmuje profil, skład, geometrię formy, wady, akustykę i ryzyka. Nie jest projektem odlewniczym ani dopuszczeniem do montażu."},{"heading":"Sytuacja zawodowa","text":"30 kg stopu 78% Cu i 22% Sn to nominalnie 23,4 kg Cu i 6,6 kg Sn. Dla średnic 240/210 mm ścianka ma 15 mm."},{"heading":"Ćwiczenie bezpieczne","text":"Oddaj przekrój, trzy obliczenia, kartę dziesięciu ryzyk i protokół oceny wad. Wyjaśnij, czego nie można wywnioskować."},{"heading":"Analiza ryzyka i weryfikacja","text":"Uczeń musi uzasadnić wynik, wskazać dane brakujące oraz oddzielić ćwiczenie edukacyjne od pracy w odlewni."},{"heading":"Ograniczenia","text":"Realny odlew, strojenie mechaniczne i montaż wymagają wykwalifikowanego specjalisty oraz odpowiedniej dokumentacji."}],"references":[{"label":"Heritage Crafts","url":"https://heritagecrafts.org.uk/craft/bell-founding/"}],"learning":{"intro":"Projekt dydaktyczny obejmuje profil, skład, geometrię formy, wady, akustykę i ryzyka. Nie jest projektem odlewniczym ani dopuszczeniem do montażu.","situation":"30 kg stopu 78% Cu i 22% Sn to nominalnie 23,4 kg Cu i 6,6 kg Sn. Dla średnic 240/210 mm ścianka ma 15 mm.","task":"Oddaj przekrój, trzy obliczenia, kartę dziesięciu ryzyk i protokół oceny wad. Wyjaśnij, czego nie można wywnioskować.","question":"Ile cyny w modelowych 30 kg stopu o udziale 22% Sn?","options":["23,4 kg.","7,8 kg.","6,6 kg.","22 kg."],"correct":2,"example":"6,6 kg.","explanation":"ludwisarz-stop","feedback":["Błędnie. ludwisarz-stop","Błędnie. ludwisarz-stop","Poprawnie. ludwisarz-stop","Błędnie. ludwisarz-stop"]}}'::jsonb) on conflict(course_slug,lesson_no) do update set title_pl=excluded.title_pl,material=public.ta_lessons.material||excluded.material,updated_at=now();
